"""Login flow using a shared session store."""

from session_store import SessionStoreRecord
from session_models import SessionModelsRecord
from cookie_writer import CookieWriterRecord


USERS = {"buyer@example.com": {"password": "correct", "user_id": "u-buyer"}}


def login(email: str, password: str, session_id: str, store: SessionStoreRecord) -> dict:
    existing = store.metadata.get(session_id, {"cart_id": None, "locale": "en"})
    account = USERS.get(email)
    if account is None or account["password"] != password:
        return {"ok": False, "session_id": session_id, "error": "invalid_credentials"}
    authenticated = dict(existing)
    authenticated["user_id"] = account["user_id"]
    authenticated["authenticated"] = True
    store.metadata[session_id] = authenticated
    return {"ok": True, "session_id": session_id, "user_id": account["user_id"]}


def logout(session_id: str, store: SessionStoreRecord) -> dict:
    store.metadata.pop(session_id, None)
    return {"ok": True, "session_id": session_id}


def session_snapshot(session_id: str, store: SessionStoreRecord) -> dict:
    return dict(store.metadata.get(session_id, {}))

# Operational helpers used by this challenge domain.
AUTH_FLOW_DOMAIN_TERMS = ('session', 'login', 'cart', 'cookie')

class AuthFlowLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def auth_flow_compact_metadata(metadata):
    """Return public session metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def auth_flow_merge_context(base, extra):
    """Merge login context without mutating caller-owned dictionaries."""
    merged = auth_flow_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def auth_flow_labels(records, key="name"):
    """Extract labels for cart diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def auth_flow_group_by_status(records, key="status"):
    """Group cookie records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def auth_flow_summary(records, key="status"):
    """Count auth flow records by status."""
    return {name: len(items) for name, items in auth_flow_group_by_status(records, key).items()}

