from auth_flow import login, session_snapshot
from session_store import SessionStoreRecord


def store_with_anon():
    return SessionStoreRecord("sessions", metadata={"anon-1": {"cart_id": "cart-9", "locale": "en-AU"}})


def test_successful_login_authenticates_user():
    result = login("buyer@example.com", "correct", "anon-1", store_with_anon())
    assert result["ok"] is True and result["user_id"] == "u-buyer"


def test_successful_login_rotates_session_id():
    result = login("buyer@example.com", "correct", "anon-1", store_with_anon())
    assert result["session_id"] != "anon-1"


def test_rotated_session_preserves_cart():
    store = store_with_anon()
    result = login("buyer@example.com", "correct", "anon-1", store)
    assert session_snapshot(result["session_id"], store)["cart_id"] == "cart-9"


def test_old_anonymous_session_is_removed_after_rotation():
    store = store_with_anon()
    login("buyer@example.com", "correct", "anon-1", store)
    assert "anon-1" not in store.metadata


def test_failed_login_keeps_existing_session_id():
    result = login("buyer@example.com", "wrong", "anon-1", store_with_anon())
    assert result["session_id"] == "anon-1"


def test_failed_login_does_not_mark_session_authenticated():
    store = store_with_anon()
    login("buyer@example.com", "wrong", "anon-1", store)
    assert session_snapshot("anon-1", store).get("authenticated") is None


def test_unknown_user_is_rejected():
    assert login("nobody@example.com", "correct", "anon-1", store_with_anon())["error"] == "invalid_credentials"


def test_locale_survives_successful_login():
    store = store_with_anon()
    result = login("buyer@example.com", "correct", "anon-1", store)
    assert session_snapshot(result["session_id"], store)["locale"] == "en-AU"


def test_common_wrong_fix_does_not_drop_safe_anonymous_data():
    store = store_with_anon()
    result = login("buyer@example.com", "correct", "anon-1", store)
    assert session_snapshot(result["session_id"], store)["cart_id"] == "cart-9"


def test_authenticated_session_contains_user_marker():
    store = store_with_anon()
    result = login("buyer@example.com", "correct", "anon-1", store)
    assert session_snapshot(result["session_id"], store)["authenticated"] is True
